mapper.select:
SELECT c.CUSTOMER_ID, c.FULL_NAME, r.REGION_NAME, DECODE(c.STATUS_FLAG, 'A', 'Active', 'S', 'Suspended', 'Closed') AS STATUS_TEXT FROM CUSTOMERS c, REGIONS r WHERE c.REGION_CODE = r.REGION_CODE(+)
AND c.REGION_CODE = #{regionCode}
ORDER BY c.FULL_NAME

SELECT * FROM (
  SELECT a.*, ROWNUM AS RN FROM (
    SELECT CUSTOMER_ID, FULL_NAME, EMAIL, REGION_CODE
    FROM CUSTOMERS
    WHERE STATUS_FLAG = 'A'
    ORDER BY FULL_NAME
  ) a
  WHERE ROWNUM <= #{endRow}
)
WHERE RN > #{startRow}

SELECT CUSTOMER_ID, FULL_NAME, EMAIL
FROM CUSTOMERS
WHERE NVL(LAST_LOGIN, CREATED_ON) < TRUNC(SYSDATE) - #{inactiveDays}
